        ms.head = temp;
      }

      function pop(ms) {
        if (ms.head == null) {
          console.log("stack underflow");
          return 0;
        } else {
          temp = ms.head;
          ms.head = ms.head.next;
          var popped = temp.data;
          delete temp;
          return popped;
        }
      }

      // making the next pointer of tail of
